//Not used anywhere
//email template for giftcards.
exports.giftCards = (data) => {
  let cardData = "";
  data.cards.forEach((cd) => {
    cardData += `<tr><td>${cd.cardNumber}</td><td>${cd.cardPin}</td><td>${cd.activationCode
      }</td><td>${cd.amount}</td><td>${moment(cd.validity).format(
        "DD-MM-YY hh-mm",
      )}</td></tr>`;
  });
  return `<!DOCTYPE html><html>
<head><title>CardNumber Details</title>
    <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/4.0.0/css/bootstrap.min.css">
    </head>
    <body>
    <div class="container">
    <h1 style="text-align:center">Card Number Details</h1>
    <table class="table">
    <thead><tr><th>Card No</th><th>PIN</th><th>ActivationCode</th><th>Amount</th><th>Validity</th></tr></thead>
    <tbody>${cardData}
    </tbody></table>
    </div>
    <script src="https://maxcdn.bootstrapcdn.com/bootstrap/4.0.0/js/bootstrap.min.js"></script>
    </body>
    </html>`;
};

